function vocabulary(module, lessonTitle, lang) {
  const [a, b, c] = module.vocab.map((item) => pick(item, lang));
  const definitions = {
    fr: [`Concept central de ${lessonTitle}, défini par une règle observable plutôt que par une préférence.`, `Mesure ou structure qui rend la décision concernant ${lessonTitle} comparable et reproductible.`, `Limite de contrôle utilisée pour vérifier que ${lessonTitle} améliore le système sans déplacer le problème.`],
    en: [`A central ${lessonTitle} concept defined by an observable rule rather than preference.`, `A measure or structure that makes the ${lessonTitle} decision comparable and reproducible.`, `A control boundary used to verify that ${lessonTitle} improves the system without moving the problem elsewhere.`],
    ar: [`مفهوم محوري في ${lessonTitle} تحدده قاعدة قابلة للملاحظة لا تفضيل شخصي.`, `قياس أو بنية تجعل قرار ${lessonTitle} قابلًا للمقارنة وإعادة التنفيذ.`, `حد تحكم للتحقق من أن ${lessonTitle} يحسن النظام من دون نقل المشكلة إلى مكان آخر.`],
  }[lang];
  return [a, b, c].map((term, index) => ({ term, definition: definitions[index] }));
}

function buildContent(module, spec, nextSpec, lang, source, filename) {
  const c = copy[lang];
  const title = pick(spec.title, lang);
  const focus = pick(spec.focus, lang);
  const artifact = pick(spec.artifact, lang);
  const nextTitle = pick(nextSpec.title, lang);
  const checked = source.replace("- [ ]", "- [x]") + `\n- ${lang === "fr" ? "Décision vérifiée" : lang === "en" ? "Verified decision" : "قرار متحقق"}: ${title}`;
  return {
    title,
    prerequisites: [c.prerequisite],
    objectives: [c.objective(title), c.objective(artifact), c.objective(focus)],
    mentalModel: c.mental(focus),
    analogy: c.analogy(title),
    explanation: [c.explain1(focus), c.explain2(title), c.explain3(artifact)],
    vocabulary: vocabulary(module, title, lang),
    generalApplication: c.general(title),
    lecomaxApplication: c.lecomax(artifact),
    commands: ["npm run dev", `# ${c.manual}`],
    expectedResult: c.expected(artifact),
    commonErrors: [
      { symptom: c.symptom1(title), cause: c.cause1, fix: c.fix1(title) },
      { symptom: c.symptom2(title), cause: c.cause2, fix: c.fix2 },
    ],
    exercise: {
      task: c.task(artifact), steps: c.steps, hints: c.hints,
      solutionExplanation: c.solution(title, artifact), solutionCode: checked,
    },
    quiz: { question: c.quiz(title), options: c.options, correctIndex: 1, explanation: c.quizExplain(title) },
    recap: c.recap(title, artifact),
    next: c.next(title, nextTitle),
  };
}

function buildLesson(module, spec, index, nextSpec) {
  const filename = `exercises/${module.order}-${module.id}/${spec.id}.md`;
  const source = [
    `# ${spec.title.en}`,
    `- [ ] Customer problem: ${spec.focus.en}`,
    `- [ ] Deliverable: ${spec.artifact.en}`,
    `- [ ] Mobile, keyboard, and long-content review`,
    `- [ ] Primary metric plus margin, trust, and satisfaction guardrails`,
    `- [ ] Official reference: ${spec.reference}`,
    `- [ ] Decision: keep, revise, or stop after evidence`,
  ].join("\n");
  const annotations = Object.fromEntries(langs.map((lang) => [lang, [
    { lines: "1-3", label: lang === "fr" ? `Cadre le problème et le livrable précis de ${pick(spec.title, lang)} avant toute exécution.` : lang === "en" ? `Frames the exact problem and deliverable for ${pick(spec.title, lang)} before execution.` : `يحدد المشكلة والمخرج الدقيق لموضوع ${pick(spec.title, lang)} قبل التنفيذ.` },
    { lines: "4-7", label: lang === "fr" ? "Ajoute les contrôles, la source officielle et une décision fondée sur les preuves plutôt que sur l’intuition." : lang === "en" ? "Adds checks, the official source, and an evidence-based decision instead of intuition." : "يضيف الفحوص والمصدر الرسمي وقرارًا مبنيًا على الدليل بدل الحدس." },
  ]]));
  return {
    id: spec.id, order: index, language: "markdown", filename, source, annotations,
    locales: Object.fromEntries(langs.map((lang) => [lang, buildContent(module, spec, nextSpec, lang, source, filename)])),
  };
}

export const modules = curricula.map((module, moduleIndex) => {
  const withOrder = { ...module, order: moduleIndex + 28 };
  return {
    id: module.id,
    order: withOrder.order,
    icon: module.icon,
    color: module.color,
    files: [{ path: "README.md", mode: "existing" }],
    locales: Object.fromEntries(langs.map((lang) => [lang, { title: pick(module.title, lang), summary: pick(module.summary, lang) }])),
    lessons: module.lessons.map((spec, index) => {
      const nextModule = curricula[moduleIndex + 1] ?? curricula[0];
      const nextSpec = module.lessons[index + 1] ?? nextModule.lessons[0];
      return buildLesson(withOrder, spec, index, nextSpec);
    }),
  };
});

export default modules;
